/**
 * Shared UI schema vocabulary for BFF controllers.
 *
 * Rules:
 *  - All enums are sourced from @bk-dash/contracts-typescript/wire/enums
 *    (the cross-language source of truth). No BFF-local enums.
 *  - Reuses SignedMonetaryAmountSchema from @shared/objects.
 *  - Phase 0 FREEZE: do not edit these shapes after Phase 1 fan-out begins.
 */

import { z } from '@bk-dash/core-typescript'
import {
	CurrencyCode,
	MarketingPlatform,
	GoalType,
	PixelEventType,
	AdAttribution,
	DisputeStatus,
	GatewayFeeKind,
	CostKind,
	DayOfWeek,
	DayPeriod,
	TimeFrequency,
	OperationalCostFlow,
	OperationalCostRecurrency,
} from '@bk-dash/contracts-typescript/wire/enums'

// ---------------------------------------------------------------------------
// Currency atom
// ---------------------------------------------------------------------------

/** Partial record of ISO-4217 currency → raw numeric value (not cents).
 *  Mirrors CurrencyObj / TotalByCurrency from the old backend. */
export const CurrencyAmountSchema = z.record(z.enum(CurrencyCode), z.number())

// ---------------------------------------------------------------------------
// Metric atoms
// ---------------------------------------------------------------------------

/** KPI atom: current-period value + period-over-period delta fraction.
 *  `deltaPct` is null when there is no prior period to compare against.
 *  Value is a raw number in the display currency (not cents). */
export const MetricSchema = z.object({
	value: z.number(),
	deltaPct: z.number().nullable(),
})

/** Multi-currency variant of Metric used in consolidated (multi-store) views. */
export const CurrencyMetricSchema = z.object({
	value: CurrencyAmountSchema,
	deltaPct: z.number().nullable(),
})

// ---------------------------------------------------------------------------
// Segmented decomposition helper
// ---------------------------------------------------------------------------

/** Returns a schema of `{ total: MetricSchema, segments: Record<key, MetricSchema> }`.
 *  Pass a native enum object whose values are the segment identifiers. */
export function segmented<T extends Record<string, string>>(enumObject: T) {
	return z.object({
		total: MetricSchema,
		segments: z.record(z.enum(enumObject), MetricSchema),
	})
}

// ---------------------------------------------------------------------------
// Segmented breakdowns (keyed by BFF enums)
// ---------------------------------------------------------------------------

export const CostBreakdownSchema = segmented(CostKind)
export const AdsByPlatformSchema = segmented(MarketingPlatform)
export const AdsByTypeSchema = segmented(AdAttribution)
export const GatewayFeeSchema = segmented(GatewayFeeKind)
export const ChargebackByStatusSchema = segmented(DisputeStatus)

// ---------------------------------------------------------------------------
// Named breakdowns (tooltip data — no presentation strings)
// ---------------------------------------------------------------------------

export const FeesBreakdownSchema = z.object({
	gateway: GatewayFeeSchema,
	checkout: MetricSchema,
	chargeback: MetricSchema,
})

export const AdsBreakdownSchema = z.object({
	total: MetricSchema,
	byPlatform: AdsByPlatformSchema,
	byType: AdsByTypeSchema,
	tax: MetricSchema,
	cpa: MetricSchema,
	roi: MetricSchema,
	roas: MetricSchema,
})

export const ChargebackBreakdownSchema = z.object({
	byStatus: ChargebackByStatusSchema,
	fees: MetricSchema,
})

export const TaxesBreakdownSchema = z.object({
	ads: MetricSchema,
	others: MetricSchema,
})

export const ProductCostBreakdownSchema = z.object({
	product: MetricSchema,
	shipping: MetricSchema,
})

// ---------------------------------------------------------------------------
// KPIs
// ---------------------------------------------------------------------------

export const KpisSchema = z.object({
	revenue: MetricSchema,
	profit: MetricSchema,
	margin: MetricSchema,
	orders: MetricSchema,
	averageTicket: MetricSchema,
	unitsSold: MetricSchema,
	costs: CostBreakdownSchema,
})

/** Per-store KPIs keyed by StoreIntegrationId (UUID string). Each store is mono-currency. */
export const PerStoreKpisSchema = z.record(z.string(), KpisSchema)

// ---------------------------------------------------------------------------
// Consolidated multi-currency KPIs (multi-store dashboard)
// ---------------------------------------------------------------------------

export const CurrencyCostBreakdownSchema = z.object({
	total: CurrencyMetricSchema,
	segments: z.record(z.enum(CostKind), CurrencyMetricSchema),
})

export const ConsolidatedKpisSchema = z.object({
	revenue: CurrencyMetricSchema,
	profit: CurrencyMetricSchema,
	margin: MetricSchema,
	orders: MetricSchema,
	averageTicket: CurrencyMetricSchema,
	unitsSold: MetricSchema,
	costs: CurrencyCostBreakdownSchema,
})

// ---------------------------------------------------------------------------
// Operational costs
// ---------------------------------------------------------------------------

export const OperationalCostItemSchema = z.object({
	id: z.string(),
	name: z.string(),
	flow: z.enum(OperationalCostFlow),
	frequency: z.enum(OperationalCostRecurrency),
	amount: z.number(),
	currency: z.enum(CurrencyCode),
	startDate: z.iso.datetime({ offset: true }),
	endDate: z.iso.datetime({ offset: true }).nullable(),
})

export const OperationalCostsSchema = z.object({
	total: MetricSchema,
	items: z.array(OperationalCostItemSchema),
})

// ---------------------------------------------------------------------------
// Profile alerts (discriminated union by `kind`)
// ---------------------------------------------------------------------------

const ProfileAlertBase = z.object({
	id: z.string(),
	platform: z.enum(MarketingPlatform),
	profileId: z.string(),
	displayName: z.string(),
})

export const ReconnectProfileAlertSchema = ProfileAlertBase.extend({
	kind: z.literal('reconnectProfile'),
})

export const SyncErrorAlertSchema = ProfileAlertBase.extend({
	kind: z.literal('syncError'),
	lastSyncedAt: z.iso.datetime({ offset: true }).nullable(),
})

export const ProfileAlertSchema = z.discriminatedUnion('kind', [ReconnectProfileAlertSchema, SyncErrorAlertSchema])

// ---------------------------------------------------------------------------
// Income graph (revenue/profit over time)
// ---------------------------------------------------------------------------

export const IncomeGraphBucketSchema = z.object({
	label: z.string(),
	orders: z.number(),
	revenue: CurrencyAmountSchema,
	profit: CurrencyAmountSchema,
	marketingCost: CurrencyAmountSchema,
	productCost: CurrencyAmountSchema,
	fees: CurrencyAmountSchema,
	taxes: CurrencyAmountSchema,
})

export const IncomeGraphSchema = z.object({
	data: z.array(IncomeGraphBucketSchema),
})

// ---------------------------------------------------------------------------
// Sales-by-* analytical breakdowns (same bucket, keyed by enum/hour)
// ---------------------------------------------------------------------------

export const SalesByDayOfWeekSchema = z.record(z.enum(DayOfWeek), IncomeGraphBucketSchema)

export const SalesByDayPeriodSchema = z.record(z.enum(DayPeriod), IncomeGraphBucketSchema)

/** Keys are string hour numbers '0'..'23'. */
export const SalesByHourSchema = z.record(z.string(), IncomeGraphBucketSchema)

export const SalesByRegionSchema = z.record(
	z.string(),
	z.object({
		state: z.string(),
		country: z.string(),
		total: CurrencyAmountSchema,
		count: z.number(),
	}),
)

// ---------------------------------------------------------------------------
// Recommended apps (shared showcase — consumed by ~6 screens)
// ---------------------------------------------------------------------------

export const RecommendedAppSchema = z.object({
	id: z.string(),
	name: z.string(),
	logoUrl: z.url(),
	rating: z.number(),
	ratingCount: z.number(),
	description: z.string(),
	installUrl: z.url(),
})

export const ListRecommendedAppsOutputSchema = z.object({
	items: z.array(RecommendedAppSchema),
	advertiseUrl: z.url(),
})

// ---------------------------------------------------------------------------
// Convenience re-exports (already in contracts/wire) so BFF query inputs can
// import the UI vocabulary from a single location.
// ---------------------------------------------------------------------------
export { GoalType, PixelEventType, TimeFrequency }

import { z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { NotificationKind } from '@bk-dash/contracts-typescript/wire/enums'

export const PushNotificationSchema = z.object({
	userId: z.uuid(),
	kind: z.enum(NotificationKind),
	payload: z.record(z.string(), z.unknown()),
})
export type PushNotification = Z.infer<typeof PushNotificationSchema>

export abstract class PushDeliveryService {
	abstract deliver(notification: PushNotification): Promise<void>
}

