package nuvemshop

import (
	"encoding/json"
	"fmt"
	"net/url"
	"strconv"
	"strings"

	"template/api-go/internal/sync/entities"
	"template/api-go/internal/sync/objects"
	"template/api-go/internal/sync/services/pipelines"
	wire "template/contracts-go/wire"
)

// PlatformID is the wire enum value all Nuvemshop normalizers register under.
const PlatformID = string(wire.SalesPlatformNUVEM_SHOP)

// ErrNormalizerBadPayload is the sentinel a normalizer returns on any
// malformed-but-skippable provider row. The pipeline counts + logs the skip;
// the run continues.
var ErrNormalizerBadPayload = fmt.Errorf("normalizer: malformed provider payload (row skipped)")

// OrderNormalizer maps a single raw Nuvemshop order JSON to entities.OrderInput.
type OrderNormalizer struct{}

// NewOrderNormalizer constructs the order normalizer.
func NewOrderNormalizer() *OrderNormalizer { return &OrderNormalizer{} }

// Platform returns the platform identifier.
func (n *OrderNormalizer) Platform() string { return PlatformID }

// Normalize maps a raw Nuvemshop order JSON byte slice to entities.OrderInput.
// Wraps errors with ErrNormalizerBadPayload for skippable malformed rows.
func (n *OrderNormalizer) Normalize(raw []byte, in pipelines.RunInput) (entities.OrderInput, error) {
	var o NuvemshopOrder
	if err := json.Unmarshal(raw, &o); err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: %v", ErrNormalizerBadPayload, err)
	}
	if o.ID == 0 {
		return entities.OrderInput{}, fmt.Errorf("%w: missing id", ErrNormalizerBadPayload)
	}
	if o.CreatedAt.IsZero() {
		return entities.OrderInput{}, fmt.Errorf("%w: missing created_at", ErrNormalizerBadPayload)
	}

	currency := o.Currency
	if currency == "" {
		currency = "BRL" // Nuvemshop is primarily BR; fall back safely
	}

	subtotalCents, err := parseDecimalToCents(o.Subtotal)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: subtotal: %v", ErrNormalizerBadPayload, err)
	}
	discountCents, err := parseDecimalToCents(o.Discount)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: discount: %v", ErrNormalizerBadPayload, err)
	}
	totalCents, err := parseDecimalToCents(o.Total)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: total: %v", ErrNormalizerBadPayload, err)
	}
	shippingCents, err := parseDecimalToCents(o.ShippingCostCustomer)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: shipping: %v", ErrNormalizerBadPayload, err)
	}

	subtotalMA, err := objects.NewMonetaryAmount(subtotalCents, currency)
	if err != nil {
		return entities.OrderInput{}, fmt.Errorf("%w: subtotal currency: %v", ErrNormalizerBadPayload, err)
	}
	discountMA, _ := objects.NewMonetaryAmount(discountCents, currency)
	totalMA, _ := objects.NewMonetaryAmount(totalCents, currency)
	shippingMA, _ := objects.NewMonetaryAmount(shippingCents, currency)
	// Nuvemshop does not expose a tax total separately — zero in the canonical currency.
	taxMA, _ := objects.NewMonetaryAmount(0, currency)

	externalID := strconv.FormatInt(o.ID, 10)

	// Line items
	lines := make([]entities.OrderLine, 0, len(o.Products))
	for _, item := range o.Products {
		if item.Quantity <= 0 {
			continue
		}
		line, lineErr := mapNuvemshopLineItem(item, externalID, currency)
		if lineErr != nil {
			// Malformed line item — skip the order.
			return entities.OrderInput{}, fmt.Errorf("%w: line item %d: %v", ErrNormalizerBadPayload, item.ID, lineErr)
		}
		lines = append(lines, line)
	}

	customerName := o.ContactName
	if customerName == "" && o.Customer != nil {
		customerName = o.Customer.Name
	}
	contactEmail := o.ContactEmail
	if contactEmail == "" && o.Customer != nil {
		contactEmail = o.Customer.Email
	}
	// Nuvemshop orders always have some contact info; use fallback email only
	// as a last resort so the handler's customerEmail field is populated.
	var customerEmailPtr *string
	if contactEmail != "" {
		customerEmailPtr = &contactEmail
	}
	var customerNamePtr *string
	if customerName != "" {
		customerNamePtr = &customerName
	}

	// Description synthesized from order number (matches source behavior).
	var description *string
	if o.Number != 0 {
		desc := "#" + strconv.FormatInt(o.Number, 10)
		description = &desc
	}

	// CartToken (Nuvemshop uses `token`).
	var cartToken *string
	if o.Token != "" {
		t := o.Token
		cartToken = &t
	}

	// UTM preference order: customer_visit.utm_parameters (modern structured field)
	// → landing_url query string → storefront fallback.
	utm := buildUTM(o.CustomerVisit, o.LandingURL, o.Storefront)

	return entities.OrderInput{
		Platform:                   PlatformID,
		ExternalID:                 externalID,
		ExternalCreatedAt:          o.CreatedAt.Time,
		StoreID:                    in.StoreID,
		StoreIntegrationID:         in.StoreIntegrationID,
		StoreIntegrationExternalID: in.StoreIntegrationExternalID,
		Description:                description,
		CustomerEmail:              customerEmailPtr,
		CustomerName:               customerNamePtr,
		CustomerPhoneNumber:        nil, // Nuvemshop exposes contact_phone as string only
		ShippingAddress:            nil, // billing addr is a string blob — no structured address
		Subtotal:                   subtotalMA,
		DiscountTotal:              discountMA,
		ShippingTotal:              shippingMA,
		TaxTotal:                   taxMA,
		Total:                      totalMA,
		PresentmentMoney:           nil,
		SettlementMoney:            nil,
		PaymentStatus:              mapPaymentStatus(o.PaymentStatus),
		PaymentMethod:              mapPaymentMethod(o.PaymentDetails.Method),
		PaymentGateway:             mapGateway(o.Gateway),
		Lines:                      lines,
		Transactions:               nil,
		CartToken:                  cartToken,
		Utm:                        utm,
		IsDraft:                    false,
		IsManual:                   false,
	}, nil
}

func mapNuvemshopLineItem(item NuvemshopOrderItem, orderExternalID, currency string) (entities.OrderLine, error) {
	unitPriceCents, err := parseDecimalToCents(item.Price)
	if err != nil {
		return entities.OrderLine{}, err
	}
	subtotalCents := unitPriceCents * int64(item.Quantity)
	subtotalMA, _ := objects.NewMonetaryAmount(subtotalCents, currency)
	zeroMA, _ := objects.NewMonetaryAmount(0, currency)

	productExt := strconv.FormatInt(item.ProductID, 10)
	variantExt := strconv.FormatInt(item.VariantID, 10)

	return entities.NewOrderLine(entities.OrderLineInput{
		Platform:          PlatformID,
		OrderExternalID:   orderExternalID,
		ExternalLineID:    strconv.FormatInt(item.ID, 10),
		ProductExternalID: productExt,
		VariantExternalID: variantExt,
		Quantity:          item.Quantity,
		SubtotalPrice:     subtotalMA,
		Discount:          zeroMA,
		Tax:               zeroMA,
		TotalPrice:        subtotalMA,
	})
}

// parseDecimalToCents converts "100.50" → 10050. Mirrors the Shopify normalizer helper.
func parseDecimalToCents(s string) (int64, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0, nil
	}
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	parts := strings.SplitN(s, ".", 2)
	whole, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil {
		return 0, err
	}
	cents := whole * 100
	if len(parts) == 2 {
		frac := parts[1]
		switch len(frac) {
		case 0:
			// "100." — treat as whole
		case 1:
			d, err := strconv.ParseInt(frac, 10, 64)
			if err != nil {
				return 0, err
			}
			cents += d * 10
		default:
			d, err := strconv.ParseInt(frac[:2], 10, 64)
			if err != nil {
				return 0, err
			}
			cents += d
		}
	}
	if neg {
		cents = -cents
	}
	return cents, nil
}

func mapPaymentStatus(s string) string {
	switch s {
	case "paid":
		return string(wire.PaymentStatusPAID)
	case "pending":
		return string(wire.PaymentStatusPENDING)
	case "authorized":
		return string(wire.PaymentStatusAUTHORIZED)
	case "partially_paid":
		return string(wire.PaymentStatusPARTIALLY_PAID)
	case "refunded":
		return string(wire.PaymentStatusREFUNDED)
	case "partially_refunded":
		return string(wire.PaymentStatusPARTIALLY_REFUNDED)
	case "voided", "abandoned":
		return string(wire.PaymentStatusVOIDED)
	default:
		return string(wire.PaymentStatusPENDING)
	}
}

func mapPaymentMethod(method string) string {
	switch method {
	case "credit_card":
		return string(wire.PaymentMethodCREDIT_CARD)
	case "debit_card":
		return string(wire.PaymentMethodDEBIT_CARD)
	case "boleto":
		return string(wire.PaymentMethodBANK_SLIP)
	case "pix":
		return string(wire.PaymentMethodPIX)
	default:
		return string(wire.PaymentMethodOTHER)
	}
}

// mapGateway normalizes the Nuvemshop gateway field to a wire PaymentGateway.
// Nuvemshop's gateway field is typically a lowercase descriptive slug.
func mapGateway(name string) string {
	if name == "" {
		return string(wire.PaymentGatewayUNKNOWN)
	}
	n := strings.ToLower(strings.ReplaceAll(strings.ReplaceAll(name, " ", "_"), ".", "_"))
	switch {
	case strings.Contains(n, "pagar_me") || strings.Contains(n, "pagarme"):
		return string(wire.PaymentGatewayPAGAR_ME)
	case strings.Contains(n, "mercadopago") || strings.Contains(n, "mercado_pago"):
		return string(wire.PaymentGatewayMERCADOPAGO)
	case strings.Contains(n, "appmax"):
		return string(wire.PaymentGatewayAPPMAX)
	case strings.Contains(n, "stripe"):
		return string(wire.PaymentGatewaySTRIPE)
	case strings.Contains(n, "paypal"):
		return string(wire.PaymentGatewayPAYPAL)
	case strings.Contains(n, "yever"):
		return string(wire.PaymentGatewayYEVER)
	default:
		return string(wire.PaymentGatewayUNKNOWN)
	}
}

// buildUTM extracts UTM data in this preference order:
//  1. `customer_visit.utm_parameters` — Nuvemshop's modern structured field
//     carrying all 5 standard UTMs as nullable strings.
//  2. `landing_url` query string — fallback for older orders. Parses
//     utm_source/medium/campaign/term/content.
//  3. `storefront` — final fallback mapping marketplace integrations
//     (meli → MERCADOLIBRE, pos → POS) when no UTM is present.
//
// Returns nil only when every source is empty.
func buildUTM(cv *NuvemshopCustomerVisit, landingURL, storefront string) *objects.UtmTags {
	source := ""
	medium := ""
	campaign := ""
	term := ""
	content := ""

	// 1. customer_visit.utm_parameters (preferred)
	if cv != nil && cv.UtmParameters != nil {
		p := cv.UtmParameters
		if p.UtmSource != nil {
			source = mapUTMSource(*p.UtmSource)
		}
		if p.UtmMedium != nil {
			medium = *p.UtmMedium
		}
		if p.UtmCampaign != nil {
			campaign = *p.UtmCampaign
		}
		if p.UtmTerm != nil {
			term = *p.UtmTerm
		}
		if p.UtmContent != nil {
			content = *p.UtmContent
		}
	}

	// 2. landing_url query string (fallback for fields not on customer_visit)
	if landingURL != "" {
		if u, err := url.Parse(landingURL); err == nil {
			q := u.Query()
			if source == "" {
				source = mapUTMSource(q.Get("utm_source"))
			}
			if medium == "" {
				medium = q.Get("utm_medium")
			}
			if campaign == "" {
				campaign = q.Get("utm_campaign")
			}
			if term == "" {
				term = q.Get("utm_term")
			}
			if content == "" {
				content = q.Get("utm_content")
			}
		}
	}

	// 3. storefront fallback for source only
	if source == "" {
		source = storefrontToSource(storefront)
	}

	if source == "" && medium == "" && campaign == "" && term == "" && content == "" {
		return nil
	}
	utm := &objects.UtmTags{}
	if source != "" {
		utm.Source = &source
	}
	if medium != "" {
		utm.Medium = &medium
	}
	if campaign != "" {
		utm.Campaign = &campaign
	}
	if term != "" {
		utm.Term = &term
	}
	if content != "" {
		utm.Content = &content
	}
	return utm
}

func mapUTMSource(s string) string {
	switch strings.ToLower(s) {
	case "":
		return ""
	case "facebook", "fb", "instagram", "ig":
		return "FACEBOOK"
	case "google", "gg":
		return "GOOGLE"
	default:
		return s
	}
}

func storefrontToSource(s string) string {
	switch s {
	case "meli":
		return "MERCADOLIBRE"
	case "pos":
		return "POS"
	default:
		return ""
	}
}

